settings.custom_code:
{% assign paddle_table = product.metafields.custom.pickleball_paddle.value %}
{% if paddle_table %}
  <style>
    .paddle-specs { margin-top: 32px; }
    .paddle-specs__table-wrap { overflow-x: auto; }
    .paddle-specs table {
      width: 100%;
      border-collapse: collapse;
      font-size: 12px;
      min-width: 900px;
      letter-spacing: 0.04em;
      color: #111;
    }
    .paddle-specs thead tr {
      background: #000;
      border-bottom: 2px solid #000;
    }
    .paddle-specs th {
      background: #000;
      color: #fff;
      padding: 14px 20px;
      text-align: left;
      font-weight: 600;
      text-transform: uppercase;
      letter-spacing: 0.12em;
      font-size: 12px;
      white-space: nowrap;
    }
    .paddle-specs th:first-child { padding-left: 20px; }
    .paddle-specs th:last-child { padding-right: 20px; }
    .paddle-specs td {
      padding: 14px 20px;
      border-bottom: 1px solid #ebebeb;
      white-space: nowrap;
      color: #222;
      vertical-align: middle;
    }
    .paddle-specs td:first-child {
      font-weight: 700;
      color: #000;
      font-size: 12px;
      letter-spacing: 0.06em;
      text-transform: uppercase;
      padding-left: 20px;
    }
    .paddle-specs td:last-child { padding-right: 20px; }
    .paddle-specs tbody tr:nth-child(odd) { background: #fff; }
    .paddle-specs tbody tr:nth-child(even) { background: #fafafa; }
    .paddle-specs tbody tr {
      transition: background 0.15s ease, box-shadow 0.15s ease;
    }
    .paddle-specs tbody tr:hover {
      background: #f2f2f2;
      box-shadow: inset 4px 0 0 #000;
    }
    .paddle-specs tbody tr:hover td { color: #000; }
    .paddle-specs tbody tr:last-child td { border-bottom: none; }
    @media (max-width: 768px) {
      .paddle-specs th,
      .paddle-specs td {
        padding: 11px 12px;
        font-size: 11px;
      }
      .paddle-specs th {
        font-size: 9px;
        letter-spacing: 0.09em;
      }
      .paddle-specs td:first-child,
      .paddle-specs th:first-child { padding-left: 14px; }
      .paddle-specs td:last-child,
      .paddle-specs th:last-child { padding-right: 14px; }
    }
  </style>
  <section class="paddle-specs">
    <div class="paddle-specs__table-wrap">
      <table>
        <thead>
          <tr>
            <th>Model</th>
            <th>Construction</th>
            <th>Core</th>
            <th>Performance</th>
            <th>Frame</th>
            <th>Shape</th>
            <th>Weight</th>
            <th>Paddle Length</th>
            <th>Paddle Width</th>
            <th>Core Thickness</th>
            <th>Handle Length</th>
            <th>Grip Size</th>
            <th>Swing Weight</th>
            <th>Twist Weight</th>
          </tr>
        </thead>
        <tbody>
          {% for row in paddle_table.rows.value %}
            <tr>
              <td>{{ row.model }}</td>
              <td>{{ row.construction }}</td>
              <td>{{ row.core }}</td>
              <td>{{ row.performance }}</td>
              <td>{{ row.frame }}</td>
              <td>{{ row.shape }}</td>
              <td>{{ row.weight }}</td>
              <td>{{ row.paddle_length }}</td>
              <td>{{ row.paddle_width }}</td>
              <td>{{ row.core_thickness }}</td>
              <td>{{ row.handle_length }}</td>
              <td>{{ row.grip_size }}</td>
              <td>{{ row.swing_weight }}</td>
              <td>{{ row.twist_weight }}</td>
            </tr>
          {% endfor %}
        </tbody>
      </table>
    </div>
  </section>
{% endif %}
